export const dictionaries = { it, en };

export function translate(language, key, params = {}) {
  const table = dictionaries[language] || dictionaries.it;
  const value = table[key] ?? dictionaries.it[key] ?? key;
  return value.replace(/\{(\w+)\}/g, (_, name) => params[name] ?? `{${name}}`);
}

export function createI18n({ storage, initial = "it" } = {}) {
  let language = storage?.getItem("mg-language") || initial;
  if (!(language in dictionaries)) language = "it";
  const listeners = new Set();
  return {
    t: (key, params) => translate(language, key, params),
    getLanguage: () => language,
    setLanguage(next) {
      if (!(next in dictionaries) || next === language) return;
      language = next;
      storage?.setItem("mg-language", next);
      for (const listener of listeners) listener(next);
    },
    subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener); },
  };
}

let browserStorage;
try { if (typeof window !== "undefined") browserStorage = window.localStorage; } catch {}
const current = createI18n({ storage: browserStorage, initial: "it" });
export const t = current.t;
export const getLanguage = current.getLanguage;
export const setLanguage = current.setLanguage;
export const onLanguageChange = current.subscribe;

export function applyTranslations(root = document) {
  document.documentElement.lang = getLanguage();
  for (const element of root.querySelectorAll("[data-i18n]")) {
    element.textContent = t(element.dataset.i18n);
  }
  for (const element of root.querySelectorAll("[data-i18n-placeholder]")) {
    element.placeholder = t(element.dataset.i18nPlaceholder);
  }
  for (const element of root.querySelectorAll("[data-i18n-aria]")) {
    element.setAttribute("aria-label", t(element.dataset.i18nAria));
  }
  for (const element of root.querySelectorAll("[data-i18n-title]")) {
    element.title = t(element.dataset.i18nTitle);
  }
}
